def compute(vars):
    occupied_space = vars["v1"]
    total_space = vars["v2"]

    if total_space == 0:
        return None

    portion = occupied_space / total_space
    return {
        "value": portion,
        "trace": {
            "occupied_space": occupied_space,
            "total_space": total_space,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio"
            }
        }
    }
